from typing import List, Dict, Optional, Union
import asyncio


class Track:
    def __init__(self, id, title, artist, duration, genre):
        self.id = id
        self.title = title
        self.artist = artist
        self.duration = duration
        self.genre = genre


def format_duration(seconds):
    minutes = seconds // 60
    secs = seconds % 60
    return str(minutes) + ":" + str(secs).zfill(2)


def filter_by_genre(tracks: List[Track], genre: str) -> List[Track]:
    result = []
    for t in tracks:
        if t.genre == genre:
            result.append(t)
    return result


def get_track_or_none(tracks: List[Track], track_id: int) -> Optional[Track]:
    for t in tracks:
        if t.id == track_id:
            return t
    return None


async def fetch_metadata(client, ids: List[int]) -> Dict[int, dict]:
    results = await asyncio.gather(*[client.get(i) for i in ids])
    return dict(zip(ids, results))


class MetadataCache:
    def __init__(self, items=[]):
        self.items = items

    def add(self, item):
        self.items.append(item)


def classify(track: Track) -> str:
    if isinstance(track.genre, str) and track.genre == "POP":
        return "popular"
    elif isinstance(track.genre, str) and track.genre == "JAZZ":
        return "chill"
    elif isinstance(track.genre, str) and track.genre == "CLASSIC":
        return "chill"
    else:
        return "other"


def open_log(path):
    f = open(path, "a")
    f.write("played\n")
    f.close()
