from typing import Optional, List, Tuple, Union
import functools


class PlayHistory:
    def __init__(self, user_id: int, track_id: int, played_seconds: int, genre: str):
        self.user_id = user_id
        self.track_id = track_id
        self.played_seconds = played_seconds
        self.genre = genre


def aggregate_by_genre(histories: List[PlayHistory]) -> dict:
    result = {}
    for h in histories:
        if h.genre in result:
            result[h.genre] = result[h.genre] + h.played_seconds
        else:
            result[h.genre] = h.played_seconds
    return result


def top_tracks(histories: List[PlayHistory], n: int) -> List[Tuple[int, int]]:
    counts = {}
    for h in histories:
        if h.track_id in counts:
            counts[h.track_id] = counts[h.track_id] + 1
        else:
            counts[h.track_id] = 1
    items = list(counts.items())
    items.sort(key=lambda x: x[1], reverse=True)
    return items[:n]


def log_decorator(func):
    def wrapper(*args, **kwargs):
        print("call", func.__name__)
        return func(*args, **kwargs)
    return wrapper


@log_decorator
def play(track_id: int) -> Optional[dict]:
    if track_id <= 0:
        return None
    return {"track_id": track_id, "status": "playing"}


class StreamSession:
    def __init__(self):
        self.connection = None

    def open(self):
        self.connection = "opened"

    def close(self):
        self.connection = None


def use_session():
    s = StreamSession()
    s.open()
    play(1)
    s.close()
